 */
class Grid {
	constructor(nHori, nVert, SX, SY) {
		this.nHori = nHori;
		this.nVert = nVert;
		// grid of cells
		this.cells = [];
		for (let y = 0; y < nVert; y++) {
			this.cells[y] = [];
			for (let x = 0; x < nHori; x++) {
				this.cells[y][x] = new Cell(x * SX, y * SY, SX, SY);
			}
		}
	}

	// merge two cells to a block -> keeps rect/cube format
	mergeCells(sizes_arr = [1, 2, 3], tries = 100) {
		// console.log(`mergeCells ${sizes_arr.length}`);
		for (let it = 0; it < tries; it++) {
			const y = ~~random(this.nVert);
			const x = ~~random(this.nHori);
			const cell = this.cells[y][x]; // cell to expand

			if (cell.merge(this, x, y, sizes_arr)) return true;
		}

		return false;
	}

	// joins cells or blocks together, can be more then 4 corners in 2D, 8 corners in 3D
	joinCells(tries = 100) {
		let x1, y1, x2, y2;
		for (let it = 0; it < tries; it++) {
			if (random() < 0.5) {
				// horiz
				y1 = ~~random(this.nVert);
				y2 = y1;
				x1 = ~~random(this.nHori - 1);
				x2 = x1 + 1;
			} else {
				// vert
				x1 = ~~random(this.nVert);
				x2 = x1;
				y1 = ~~random(this.nHori - 1);
				y2 = y1 + 1;
			}
			// console.log(`grid[${y1}][${x1}].joinRect(grid[${y2}][${x1}]);`);
			if (this.cells[y1][x1].joinRect(this.cells[y2][x1])) return true;
		}

		return false;
	}

	draw(animate = true, sw = 0) {
		let numCanMerge = 0;
		for (let y = 0; y < this.cells.length; y++) {
			for (let x = 0; x < this.cells[y].length; x++) {
				var cell = this.cells[y][x];
				cell.draw(animate, sw);
			}
		}
	}

	analyze() {
		let numCells = 0, numMerged = 0, histoPts = [];
		// for (let i = 0; i < 99; i++) histoPts[i] = 0;
		for (let y = 0; y < this.nVert; y++) {
			for (let x = 0; x < this.nHori; x++) {
				var cell = this.cells[y][x];
				numCells++;
				if (!cell.canMerge) numMerged++;
				const numPts = cell.pts.length;
				if (!histoPts[numPts]) {
					histoPts[numPts] = 1;
				} else {
					histoPts[numPts]++;
				}
			}
		}
		console.log(`numCells = ${numCells}, numMerged = ${numMerged}`);
		console.log("histoPts");
		console.log(histoPts);
		console.log("\n");
	}
}


