class Cell {
  constructor(x, y, w, h) {
    //
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
    this.sclW = 1;
    this.sclH = 1;
    this.clr = color(random(100, 300), random(128), random(200));
    // this.clr = color(noise(321+x*0.007123)*200+100, noise(123+y*0.006321)*128, noise(231+(x+y)*0.05231)*200);
		if (random() < 0.1) this.clr = lerpColor(this.clr, color(255), random(0.1, 0.5));
    this.canMerge = true; // when extended (either main or sub)
    this.linkParent = null; // for sub link to main
    // corners: tl, tr, br, bl
    const p1 = { x, y };
    const p2 = { x: x + w * this.sclW, y };
    const p3 = { x: x + w * this.sclW, y: y + h * this.sclH };
    const p4 = { x, y: y + h * this.sclH };
    this.pts = [p1, p2, p3, p4]; // store corners in array
		this.center = {x: x + w * this.sclW/2, y: y + h * this.sclH/2};
  }
	// constructor

  draw(animate = true) {
    if (this.linkParent) return false;

    function noiseX(p, scl = 10) {
      return (noise(p.x, p.y, frameCount * 0.01) - 0.5) * scl;
    }
    function noiseY(p, scl = 10) {
      return (noise(p.y, p.x, frameCount * 0.01) - 0.5) * scl;
    }

		fill(this.clr);

		beginShape();
    for (let p of this.pts) {
      var x = p.x + (animate ? noiseX(p) : 0);
      var y = p.y + (animate ? noiseY(p) : 0);
      vertex(x, y);
    }
    endShape();
  }
	// draw()

	// merges cell, keeps 4 pts arr
  merge(grid, x, y, sizes_arr = [1, 2, 3]) {
		// console.log(`mergeCells ${sizes_arr.length}`);
    if (this.isOccupied) return false;

    let sclW = min(random(sizes_arr), grid.nHori - x);
    let sclH = min(random(sizes_arr), grid.nVert - y);
    if (sclW + sclH === 2) return false;

    // check if not occupied
    let canMerge = true;
    for (let j = y; j < y + sclH; j++) {
      for (let i = x; i < x + sclW; i++) {
        const other = grid.cells[j][i];
        canMerge = canMerge && other.canMerge;
      }
    }

    if (!canMerge) return false;

    // -> merge
    for (let j = y; j < y + sclH; j++) {
      for (let i = x; i < x + sclW; i++) {
        var other = grid.cells[j][i];
        other.canMerge = false; // main is also occupied
        if (this === other) continue;
        other.linkParent = this; // only child has reference to parent
      }
    }
    // adjust main cell
    this.sclW = sclW;
    this.sclH = sclH;
    var p1 = grid.cells[y][x].pts[0];
    var p2 = grid.cells[y][x + sclW - 1].pts[1];
    var p3 = grid.cells[y + sclH - 1][x + sclW - 1].pts[2];
    var p4 = grid.cells[y + sclH - 1][x].pts[3];
    this.pts = [p1, p2, p3, p4];
		this.center = {x: (p1.x+p2.x)/2, y: (p2.y+p3.y)/2};
  }
	// merge(grid, x, y, sizes_arr)

  // must be rectangle cells, consisting of each 4 points -> result 6..8 points
  joinRect(other, swapped = false) {
    // disable linkParent check for  interesting shapes, eg "]"
    if (this.linkParent) return this.linkParent.joinRect(other, swapped);
    if (other.linkParent) return this.joinRect(other.linkParent, swapped);

    let r1 = this.pts;
    let r2 = other.pts;

    // check if cells can join: each not merged and 4 points
    if (r1.length !== 4 || r2.length !== 4) {
      return;
    }

    // swap rects to be r1 top left from r2
    if (!(sameX(r1[1], r2[0]) || sameY(r1[2], r2[0]))) {
      if (swapped) return false; // no connecting edges, do nothing
      return other.joinRect(this, true); // swap rects
    }

    function samePt(p1, p2, d = 0.01) {
      return sameX(p1, p2, d) && sameY(p1, p2, d);
    }
    function sameX(p1, p2, d = 0.01) {
      return abs(p1.x - p2.x) < d;
    }
    function sameY(p1, p2, d = 0.01) {
      return abs(p1.y - p2.y) < d;
    }
    function lastPt() {
      if (joinedRects.length) return joinedRects[joinedRects.length - 1];
      return;
    }
    function insertPt(pt) {
      if (
        joinedRects.length &&
        (samePt(lastPt(), pt) || samePt(joinedRects[0], pt))
      )
        return;
      joinedRects.push(pt);
    }

    let r1Idx = 2,
      r2strIdx = 0,
      r2endIdx = 3;
    const joinedRects = [];
    insertPt(r1[0]);
    insertPt(r1[1]);

    // 2 cases: r1 left from r2 or
    // r1 is above from r2, then:
    if (!sameX(r1[1], r2[0])) {
      insertPt(r1[r1Idx++]);
      (r2strIdx = 1), (r2endIdx = 4);
    }

    // add rest points of r2
    for (let i = r2strIdx; i <= r2endIdx; i++) {
      insertPt(r2[i % r2.length]);
    }

    // add rest points of r1
    while (r1Idx < 4) {
      insertPt(r1[r1Idx++]);
    }

    // finished:
    this.canMerge = false;
    this.linkParent = null;
    other.canMerge = false;
    other.linkParent = this;
    this.pts = joinedRects;
    // return joinedRects;
		let cx = 0, cy = 0;
		for (let p of this.pts) {
			cx += p.x;
			cy += p.y;
		}
		cx /= this.pts.length;
		cy /= this.pts.length;
		this.center = {x: cx, y: cy};

    return true;
  }
	// joinRect(other, swapped = false)
}

