// same Grid class for 3D
class Grid3D {
	// dimension and sizes as array
	constructor(pos, dims, sizes) {
		this.pos = pos;
		this.dims = dims;
		this.sizes = sizes;
		// grid of cells
		this.cells = [];
		for (let z = 0; z < this.dims.z; z++) {
			this.cells[z] = [];
			for (let y = 0; y < this.dims.y; y++) {
				this.cells[z][y] = [];
				for (let x = 0; x < this.dims.x; x++) {
					this.cells[z][y][x] = new Cell3D({
						x: x * sizes.x,
						y: y * sizes.y,
						z: z * sizes.z
					}, sizes);
				}
			}
		}
	}

	// merge two cells to a block -> keeps rect/cube format
	mergeCells(sizes_arr = [1, 2, 3], tries = 100) {
		// console.log(`mergeCells ${sizes_arr.length}`);
		for (let it = 0; it < tries; it++) {
			var x = ~~random(this.dims.x);
			var y = ~~random(this.dims.y);
			const z = ~~random(this.dims.z);
			var cell = this.cells[z][y][x]; // cell to expand

			if (cell.merge(this, {
					x,
					y,
					z
				}, sizes_arr)) return true;
		}

		return false;
	}

	// joins cells or blocks together, can be more then 4 corners in 2D, 8 corners in 3D
	joinCells(tries = 100) {
		// not implemented for 3D now
		return;

		// 2D code
		var x1, y1, x2, y2;
		for (let it = 0; it < tries; it++) {
			if (random() < 0.5) {
				// horiz
				y1 = ~~random(this.nVert);
				y2 = y1;
				x1 = ~~random(this.nHori - 1);
				x2 = x1 + 1;
			} else {
				// vert
				x1 = ~~random(this.nVert);
				x2 = x1;
				y1 = ~~random(this.nHori - 1);
				y2 = y1 + 1;
			}
			// console.log(`grid[${y1}][${x1}].joinRect(grid[${y2}][${x1}]);`);
			if (this.cells[y1][x1].joinRect(this.cells[y2][x1])) return true;
		}

		return false;
	}

	draw(animate = true, sw = 0) {
		push();
		translate(this.pos.x, this.pos.y, this.pos.z);
		translate(-this.dims.x * this.sizes.x / 2, -this.dims.y * this.sizes.y / 2, -this.dims.z * this.sizes.z / 2);
		for (let z = 0; z < this.dims.z; z++) {
			for (let y = 0; y < this.dims.y; y++) {
				for (let x = 0; x < this.dims.x; x++) {
					var cell = this.cells[z][y][x];
					cell.draw(animate, sw);
				}
			}
		}
		pop();
	}

	analyze() {
		var numCells = 0,
			numMerged = 0,
			histoPts = [];
		// for (let i = 0; i < 99; i++) histoPts[i] = 0;
		for (let z = 0; z < this.dims.z; z++) {
			for (let y = 0; y < this.dims.y; y++) {
