		};
		const p6 = {
			x: p2.x,
			y: p2.y,
			z: p5.z
		};
		const p7 = {
			x: p3.x,
			y: p3.y,
			z: p5.z
		};
		const p8 = {
			x: p4.x,
			y: p4.y,
			z: p5.z
		};
		this.pts = [p1, p2, p3, p4, p5, p6, p7, p8]; // store corners in array
		this.center = {
			x: this.pos.x + this.sizes.x * this.scales.x / 2,
			y: this.pos.y + this.sizes.y * this.scales.y / 2,
			z: this.pos.z + this.sizes.z * this.scales.z / 2
		};
