var NUM_W = 5;
var NUM_H = NUM_W;
var grid, bg, mode3D;
var myModel;

function setup() {
	mode3D = random() < 0.5;
	createCanvas(S = max(windowWidth, windowHeight), S, mode3D ? WEBGL : P2D);
	frameRate(30);
	bg = color("beige");

	const SX = width / NUM_W;
	const SY = height / NUM_H;
	grid = mode3D ? new Grid3D(
		{ x: 0, y: 0, z: 0 }, 
		{ x: NUM_W, y: NUM_H, z: NUM_H }, 
		{ x: SX, y: SY, z: SX}
	) : new Grid(NUM_W, NUM_H, SX, SY);
	for (let i = NUM_W * NUM_W; i--;) grid.mergeCells([1, 2, 3]);
	for (let i = 2 * NUM_W; i--;) grid.joinCells();
	grid.analyze();
}

function draw() {
	background(bg);
	if (mode3D) {
		orbitControl();
		lights();
		translate(0, 0, -1000);
		if (true) {
			rotateX(frameCount * 0.0321);
			rotateY(frameCount * 0.0123);
			rotateZ(frameCount * 0.0231);
		}
	}
	stroke(bg);
	strokeWeight(0);
	grid.draw(false, 20); // animate
}

function doubleClicked() {
	if (mouseButton === LEFT) {
		setup();
	}
